from pathlib import Path
import json
P=Path(__file__).parent;R=P.parents[6];qs={q['id']:q for c in json.load(open(R/'src/data/manufacturing/mechanical.json'))['checks'] for q in c['questions']}
DATA=[
[1,'Habang gumagamit ng lathe, may panginginig na iba sa karaniwan. Kung maaaring ihinto mula sa ligtas na posisyon, ano ang unang gagawin?', ['Ipagpatuloy ang machining hanggang maabot ang deadline.','Ihinto ayon sa itinakdang paraan at sabihin sa supervisor ang abnormality.','Hawakan ang gumagalaw na bahagi upang suriin ang panginginig.','Sabihin lamang sa katabi at hayaang umaandar ang makina.'],['Kung uunahin ang deadline at pababayaan ang abnormality, maaaring lumawak ang panganib at depekto.','Maaaring maging aksidente ang pinabayaang abnormality. Huwag basta mag-restart matapos stopping; kumuha ng tagubilin ayon sa workplace procedure.','May panganib na mahila kapag hinawakan ang moving parts.','Magpapatuloy ang mapanganib na kondisyon kung impormasyon lamang ang ipinasa. Gawin ang kinakailangang stop at report sa responsable.']],
[2,'Hindi narinig nang malinaw ang machining instructions at hindi alam ang rotational speed. Alin ang pinakaangkop na konsultasyon bago magsimula?', ['Hulaan at itakda ang speed na katulad ng dating produkto.','Magtanong muli matapos ang trabaho.','Sumagot lamang na “Ayos lang.”','Itanong: “Hindi ko pa natiyak ang rotational speed. Maaari po ba nating tingnan nang magkasama ang instruction sheet?”'],['Maaaring magbago ang kondisyon kapag iba ang produkto o tool; huwag mag-set mula sa hula.','Huli na ang verification at maaaring mag-machine sa maling kondisyon.','Hindi nalalaman ng kausap na hindi naunawaan, kaya walang verification.','Naipapakita nang tiyak ang hindi malinaw at naiiwasan ang maling operasyon sa pagtiyak bago magsimula.']],
[3,'Kumpleto ang kailangang hex wrenches ngunit kailangang hanapin sa drawer sa bawat paggamit. Ano ang pinakadirektang improvement?', ['Itakda at lagyan ng label ang lugar ng bawat size at ibalik doon.','Itapon pati lahat ng kailangang wrenches.','Dagdagan lamang ang bilang ng tools.','Palitan araw-araw ang taong naghahanap.'],['Nababawasan ang paghahanap at maling pagkuha sa pag-aayos ng kinakailangang bagay upang madaling makuha.','Ang sorting ay paghihiwalay ng kailangan at hindi kailangan, hindi pagtatapon pati ng kinakailangang tools.','Hindi nalulutas ang paghahanap habang hindi malinaw ang lugar.','Mananatili ang problema sa arrangement kahit palitan ang nakatalaga.']],
[4,'Nakatakda sa replacement-blade shelf na “4 hanggang 8 piraso ng parehong part number.” Sa pagsusuri ay 2 lamang. Alin sa tatlong nakatakda ang pangunahing sinusuri?', ['Takdang lugar','Takdang uri','Takdang dami','Paglilinis'],['Takdang lugar ang pagtukoy kung saan ilalagay. Dito, sinusuri kung pasok sa range ang dami.','Takdang uri ang pagtukoy sa bagay na ilalagay. Dito, bilang at hindi part number ang problema.','Takdang dami ang pagtatakda at pamamahala ng bilang. Mas kaunti ang 2 kaysa minimum na 4, kaya mag-ulat ayon sa replenishment procedure.','Paglilinis ang pag-alis ng dumi, na iba sa quantity management ng tatlong nakatakda.']],
[5,'Magdi-drill gamit ang drill press. Ano ang tamang pasya tungkol sa gloves?', ['Hindi mahihila ang manipis na gloves.','Ligtas kapag doble ang leather gloves.','Maaaring pumili ng anumang gloves kung may safety glasses.','Huwag gumamit ng gloves habang nagdi-drill dahil maaaring mahila sa umiikot na cutting tool.'],['Hindi nawawala ang entanglement hazard dahil manipis.','Hindi nalulutas ng pagdoble ang entanglement hazard.','Magkaibang hazard ang eye protection at glove entanglement.','Maaaring mahila ang gloves sa umiikot na bahagi ng drill press. Piliin ang PPE ayon sa trabaho at sundin din ang iba pang itinakdang safety controls.']],
[6,'Minsan nang nakita ang demonstration ng instructor ngunit hindi pa maipaliwanag kung paano tiyakin ang setting. Ano ang susunod sa OJT?', ['Agad gawin nang mag-isa ang production dahil nakita na minsan.','Itanong ang hindi malinaw, ipaliwanag muli, at magsanay sa saklaw na sinusuri ng instructor.','Pumili ng anumang setting at ipakita lamang ang resulta.','Isara ang manual nang hindi nagtatanong.'],['Nagpapatuloy sa independent work habang hindi pa natiyak ang pagkaunawa.','Magkaiba ang nakakita na at kayang gawin nang ligtas. Tiyakin ang pagkakaiba ng pagkaunawa, gawin sa takdang saklaw, at magpasuri.','Nakapipinsala sa quality at safety ang setting mula sa hula.','Nananatili ang hindi malinaw at hindi nasusuri ang pagkaunawa.']],
[7,'Matapos turuan ng tightening settings, anong pahayag ang pinakanakatutulong upang tiyakin ang pagkaunawa?', ['Paulit-ulit lamang na “oo” kahit hindi nauunawaan.','Sabihing dapat alam din ng iba.','Ipaliwanag sa sariling salita ang display na susuriin, numero at yunit, at stopping conditions sa abnormality.','Alalahanin ang numero lamang at alisin ang yunit.'],['Hindi nasusuri ang tiyak na pagkaunawa.','Hindi nito nasusuri ang sariling pagkaunawa.','Sa pag-ulit ng tiyak na checks, matutukoy ng instructor ang pagkakaiba ng pagkaunawa.','Magbabago ang kahulugan ng parehong numero kung iba ang yunit.']],
[8,'Itutulak sa corner ang cart na nahaharangan ng karga ang tanaw sa unahan. Alin ang tiyak na paglalarawan ng hazard?', ['Kung magpapatuloy sa corner nang mahina ang tanaw, maaaring mabangga ang pedestrian sa crossing passage.','Parang delikado.','Dapat magsikap ang nagtutulak.','Laging magdudulot ng aksidente ang cart.'],['Tiyak ang ugnayan ng cause, action, at accident, kaya madaling pag-aralan ang countermeasure.','Hindi malinaw ang hazard cause o accident.','Hindi ipinapakita ang hazard at hindi rin tiyak ang countermeasure.','Pangkalahatang konklusyon ito para sa lahat ng carts nang walang kondisyon, hindi pagsusuri ng sitwasyon.']],
[9,'Sa KYT, napagpasyahan lamang na “mag-ingat sa passage.” Paano magiging tiyak ang countermeasure?', ['Palitan ng “mas mag-ingat.”','Tiyakin ang visibility at routes at itakda ang stop/check locations ayon sa workplace rules.','Aktuwal na muling likhain ang dangerous transport method.','Talakayin lamang at balewalain ang equipment problems.'],['Hindi nagiging tiyak ang kilos sa mas matinding pag-iingat lamang.','Nililinaw ang ano, kailan, at saan upang maging maisasagawang countermeasure.','Hindi training ang KYT upang aktuwal na lumikha at subukan ang panganib.','Kailangan ding siyasatin ang equipment at environmental causes.']],
[10,'Kahit linisin ang oil sa passage, paulit-ulit itong tumatagas sa parehong lugar. Ano ang kailangan upang maiwasan ang pag-ulit?', ['Dagdagan lamang ang cleaning at huwag siyasatin ang sanhi.','Dumaan hanggang masanay sa oil.','Gawin ang itinakdang temporary response, humiling ng inspection sa leak cause, at tingnan kung umuulit matapos countermeasure.','Baguhin ng operator ang piping nang walang pahintulot.'],['Maaaring mawala ang kasalukuyang dumi ngunit nananatili ang sanhi.','Hindi nababawasan ang slipping hazard.','Nananatili ang leak cause sa cleaning lamang. Kailangan ang countermeasure sa cause at effect verification.','Maaaring lumikha ng bagong hazard ang pagbabagong hindi sumusunod sa authority at procedure.']],
[11,'Alin ang tama tungkol sa risk matapos isagawa ang countermeasure?', ['Tiyakin kung may natitira o bagong hazard at ibahagi sa kaugnay na tao.','Siguradong zero na ang accident possibility dahil may isang countermeasure.','Hindi na kailangan ang inspection records pagkatapos.','Huwag iulat ang bagong hazard dahil planado na ang ginawa.'],['Maaaring may failure o pagbabago ng sitwasyon kahit matapos countermeasure, kaya tiyakin ang effect at residual risk.','Hindi laging lubusang inaalis ng countermeasure ang lahat ng hazards.','Kailangan ang rekord bilang batayan ng effect at change verification.','Kailangan ding suriin at tugunan ang bagong hazard.']],
[12,'Sinabi ng operator na may safety glasses: “Protektado ang mata, kaya maaaring alisin ang machine guard.” Ano ang tamang pasya?', ['Napipigilan ng glasses ang lahat ng hazard bukod pa sa flying objects.','Hindi kailangan ang guard kung maikli ang trabaho.','Alisin din kung inalis ng ibang tao.','Hindi kapalit ng guard ang safety glasses; sundin din ang guard at procedure.'],['Hindi napipigilan ng eye protection ang lahat ng ibang hazards.','May exposure sa panganib kahit maikli ang oras.','Hindi batayan ang kilos ng iba upang laktawan ang safety procedure.','Pinagsasama ang PPE at equipment controls; hindi dahilan ang PPE upang i-disable ang guard.']]
]
def build(data):
 out={}
 for n,stem,options,reasons in data:
  k=f'mfg1-mechanical-formative-{n:03}';s=qs[k];assert len(options)==len(s['optionsJa'])==len(reasons)
  out[k]={'sourceHash':s['sourceHash'],'translatedDirectlyFrom':'ja','nativeReviewed':False,'domainReviewed':False,'status':'ai_translated_draft','stem':stem,'options':options,'reasons':reasons}
 return {'locale':'tl','nativeReviewed':False,'domainReviewed':False,'questions':out}
if __name__=='__main__':
 (P/'root-tl-weekly01.json').write_text(json.dumps(build(DATA),ensure_ascii=False,indent=2)+'\n');print('12completeTLweeklyquestions')
